<?php
require_once __DIR__ . '/../../cors.php';require_once __DIR__ . '/../../db/db.php';require_once __DIR__ . '/../../reusables/organization_guard.php';require_once __DIR__ . '/../../reusables/dispatch_dedup.php';header('Content-Type: application/json');$ctx=requireOrganizationAccess($pdo,'incidents.emergency_requests.read');$org=(int)$ctx['organization_id'];
try{$s=$pdo->prepare("SELECT DISTINCT er.id,er.reference_number,er.severity,er.status,er.address_text,er.barangay,er.landmark,er.description,er.requester_name,er.requester_phone,er.submitted_at,er.completed_at,ec.name category_name,da.assignment_status,da.assigned_at,a.unit_code,a.plate_number FROM emergency_requests er LEFT JOIN emergency_categories ec ON ec.id=er.emergency_category_id LEFT JOIN dispatch_assignments da ON da.emergency_request_id=er.id AND da.organization_id=? LEFT JOIN incident_offers io ON io.emergency_request_id=er.id AND io.organization_id=? LEFT JOIN ambulances a ON a.id=da.ambulance_id WHERE da.id IS NOT NULL OR io.id IS NOT NULL ORDER BY er.submitted_at DESC LIMIT 200");$s->execute([$org,$org]);$items=$s->fetchAll(PDO::FETCH_ASSOC);$linked=dedupLinkedCounts($pdo,array_column($items,'id'));foreach($items as &$x){$x['linked_count']=$linked[(int)$x['id']]??0;}unset($x);echo json_encode(['success'=>true,'items'=>$items,'stats'=>['total'=>count($items),'active'=>count(array_filter($items,fn($x)=>!in_array($x['status'],['completed','cancelled','rejected','duplicate','false_alarm'],true))),'completed'=>count(array_filter($items,fn($x)=>$x['status']==='completed'))]]);}catch(Throwable $e){error_log('Org incidents failed: '.$e->getMessage());organizationJsonError(500,'Unable to load organization incidents.');}
